private static void throwIfWriteLimitReached(Throwable ex, int depth) throws SAXException {
    if (ex == null) {
        return;
    }
    if (depth > MAX_DEPTH) {
        return;
    }
    if (ex instanceof WriteLimitReachedException) {
        throw (SAXException) ex;
    } else {
        throwIfWriteLimitReached(ex.getCause(), depth + 1);
    }
}
